public void accountTransfer(String fromId, String toId, int money)
        throws SQLException {

    Connection con = dataSource.getConnection();          // 1
    try {                                                 // 2
        con.setAutoCommit(false);                         // 3

        bizLogic(con, fromId, toId, money);               // 업무 로직 (1 줄)

        con.commit();                                     // 4
    } catch (Exception e) {                               // 5
        con.rollback();                                   // 6
        throw new IllegalStateException(e);               // 7
    } finally {                                           // 8
        release(con);                                     // 9
    }
}

private void release(Connection con) {                    // 10
    if (con != null) {                                    // 11
        try {                                             // 12
            con.setAutoCommit(true);                      // 13
            con.close();                                  // 14
        } catch (Exception e) {                           // 15
            log.info("error", e);                         // 16
        }
    }
}

